using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace MyApp.Evals.Infrastructure;

/// <summary>
/// Shared fixture that boots the Aspire AppHost and provides an <see cref="IChatClient"/>
/// resolved from the host's DI container.
/// </summary>
public sealed class EvalAppFixture : IAsyncDisposable
{
    private DistributedApplicationTestingBuilder? _builder;
    private DistributedApplication? _app;

    public IChatClient ChatClient { get; private set; } = null!;

    public async Task StartAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();

        ChatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI;

namespace MyApp.Evals.Infrastructure;

/// <summary>
/// Base class for evaluation tests. Provides the reporting infrastructure and
/// common helper methods for running evaluations.
/// </summary>
public abstract class EvalBase
{
    private static readonly EvalAppFixture s_fixture = new();
    private static ReportingConfiguration? s_reportingConfig;

    protected static IChatClient ChatClient => s_fixture.ChatClient;

    [AssemblyInitialize]
    public static async Task AssemblyInit(TestContext _)
    {
        await s_fixture.StartAsync();

        s_reportingConfig = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task AssemblyCleanup()
    {
        if (s_reportingConfig is not null)
        {
            await s_reportingConfig.DisposeAsync();
        }

        await s_fixture.DisposeAsync();
    }

    protected static ReportingConfiguration ReportingConfig =>
        s_reportingConfig ?? throw new InvalidOperationException("Reporting not initialized.");

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Directory.GetCurrentDirectory(), "eval-results");

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: path,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(ChatClient));
    }
}

