using System.ClientModel;
using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using OpenAI;

namespace MyApp.Evals.Infrastructure;

/// <summary>
/// Creates an <see cref="IChatClient"/> that targets the same Azure OpenAI deployment
/// used by the AppHost ("chat" resource → gpt-4o-mini model).
///
/// Required environment variables:
///   AZURE_OPENAI_ENDPOINT – the Azure OpenAI resource endpoint URL
///   AZURE_OPENAI_API_KEY  – (optional) API key; if omitted, DefaultAzureCredential is used
///   AZURE_OPENAI_DEPLOYMENT – (optional) deployment name; defaults to "chat"
/// </summary>
public static class ChatClientFactory
{
    public static IChatClient Create()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set the AZURE_OPENAI_ENDPOINT environment variable to your Azure OpenAI endpoint.");

        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "chat";
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY");

        AzureOpenAIClient azureClient = apiKey is not null
            ? new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(apiKey))
            : new AzureOpenAIClient(new Uri(endpoint), new Azure.Identity.DefaultAzureCredential());

        return azureClient.GetChatClient(deployment).AsIChatClient();
    }
}

