using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using MyApp.Evals.Infrastructure;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static IChatClient ChatClient => EvalSetup.ChatClient;
    private static ReportingConfiguration ReportingConfig => EvalSetup.ReportingConfig;

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await ReportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_coherently_to_greeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello! Can you introduce yourself briefly?")
        };

        var response = await ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertNoFailures(result);
    }

    [TestMethod]
    public async Task Chat_provides_relevant_answer_to_factual_question()
    {
        await using var scenario = await ReportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_provides_relevant_answer_to_factual_question));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertNoFailures(result);
    }

    [TestMethod]
    public async Task Chat_handles_multi_turn_conversation()
    {
        await using var scenario = await ReportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_handles_multi_turn_conversation));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan. What month would you recommend?")
        };

        var firstResponse = await ChatClient.GetResponseAsync(messages);
        messages.AddRange(firstResponse.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "What should I pack for that time of year?"));

        var response = await ChatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertNoFailures(result);
    }

    private static void AssertNoFailures(EvaluationResult result)
    {
        var failures = result.Metrics
            .Where(m => m.Value.Interpretation?.Rating is EvaluationRating.Unacceptable or EvaluationRating.Poor)
            .Select(m => $"{m.Key}: {m.Value.Interpretation?.Rating} - {m.Value.Reason}")
            .ToList();

        Assert.AreEqual(0, failures.Count,
            $"Evaluation failed on metrics:\n{string.Join("\n", failures)}");
    }
}

